function ManagementDashboard() {
  const { data, loading, error, reload } = useLoad(() => dashboardService.getManagementDashboardData(), [], null as any);
  const [mode, setMode] = useState<'work' | 'alert' | null>(null);
  if (loading || error || !data) return <StateBlock loading={loading} error={error} retry={reload} empty={!data} />;
  const done = data.workOrders.filter((w: any) => ['Enviado', 'Cerrado'].includes(w.status));
  const pending = data.workOrders.filter((w: any) => !['Enviado', 'Cerrado', 'Cancelado'].includes(w.status));
  const urgent = data.workOrders.filter((w: any) => ['Alta', 'Critica'].includes(w.priority));
  const openDef = data.deficiencies.filter((d: any) => !['Corregida', 'Cerrada', 'Rechazada'].includes(d.status));
  const saleAmount = Number(data.metrics.sale_amount ?? data.metrics.accepted_quote_amount ?? 0);
  const realCost = Number(data.metrics.real_cost ?? 0);
  const marginAmount = Number(data.metrics.margin_amount ?? saleAmount - realCost);
  const managementKpis = [kpiCard('Venta sin IVA', `${saleAmount.toLocaleString('es-ES')} €`, 'Aceptado/ejecutado', 'Presupuestos aceptados o ejecutados sin IVA', '/app/modulos/presupuestos?estado=aceptado'), kpiCard('Coste real', `${realCost.toLocaleString('es-ES')} €`, 'Partes visibles', 'Materiales, horas y costes auxiliares', '/app/modulos/rentabilidad'), kpiCard('Margen', `${marginAmount.toLocaleString('es-ES')} €`, 'Sin IVA', 'Venta sin IVA menos coste real', '/app/modulos/rentabilidad'), kpiCard('Clientes activos', data.metrics.clients ?? data.clients.length, 'Actual', 'Clientes visibles', '/app/clientes'), kpiCard('Equipos', data.metrics.equipment ?? 0, 'Actual', 'Inventario instalado', '/app/equipos'), kpiCard('Partes realizados', done.length, 'Actual', 'Enviados o cerrados', '/app/partes?estado=realizado'), kpiCard('Pendiente facturar', data.metrics.pending_invoice_work_orders ?? 0, 'Sin cobros reales', 'Trabajos terminados sin importe facturado', '/app/modulos/rentabilidad'), kpiCard('Garantías', `${Number(data.metrics.warranty_cost ?? 0).toLocaleString('es-ES')} €`, 'Coste real', 'Coste de partes en garantía', '/app/modulos/rentabilidad')];
  const managementAlerts = [...data.alerts, ...openDef].slice(0, 8).map((item: any) => [item.title ?? item.code, item.description ?? item.status, severityForStatus(item.status ?? item.priority), item.related_entity ? routeForAlert(item) : item.code ? `/app/deficiencias/${item.id}` : '/app/avisos'] as [string, string, Severity, string]);
  return <RoleDashboard title="Inicio Gerencia" subtitle="Visión global, rentabilidad, carga operativa y alertas estratégicas." kpis={managementKpis} quickActions={<><button onClick={() => setMode('work')}>Crear parte</button><button onClick={() => setMode('alert')}>Crear aviso</button><Link to="/app/modulos/informes">Abrir informe</Link><Link to="/app/gerencia">Consultar métricas</Link><Link to="/app/deficiencias?filtro=desviaciones">Revisar desviaciones</Link><Link to="/app/clientes">Abrir cliente</Link></>}><InteractiveBars title="Trabajos realizados frente a pendientes" values={[[ 'Realizados', done.length, '/app/partes?estado=realizado'], ['Pendientes', pending.length, '/app/partes?estado=pendiente'], ['Urgentes', urgent.length, '/app/partes?prioridad=critica']]} /><InteractiveBars title="Deficiencias por gravedad" values={['Baja','Media','Alta','Critica'].map((level) => [displayStatus(level), data.deficiencies.filter((d: any) => d.severity === level).length, `/app/deficiencias?gravedad=${level}`]) as any} /><DashboardList title="Alertas de dirección" rows={managementAlerts} empty="Sin alertas estratégicas." />{mode === 'work' && <WorkOrderForm onClose={() => setMode(null)} onSaved={() => { setMode(null); reload(); }} />}{mode === 'alert' && <AlertForm onClose={() => setMode(null)} onSaved={() => { setMode(null); reload(); }} />}</RoleDashboard>;
}

function RoleDashboard({ title, subtitle, kpis, quickActions, children }: { title: string; subtitle: string; kpis: any[]; quickActions: ReactNode; children: ReactNode }) {
  return <section className="page dashboard-page"><Breadcrumb items={['Inicio', title]} /><div className="page-head"><div><h2>{title}</h2><p>{subtitle}</p><small>Última actualización: {new Date().toLocaleTimeString('es-ES', { hour: '2-digit', minute: '2-digit' })}</small></div></div><div className="stats-grid dashboard-kpis">{kpis.map((item) => <Link key={item.label} className={`metric ${item.tone}`} to={item.route}><div>{item.icon}<span>{item.label}</span></div><strong>{item.value}</strong><small>{item.period} · {item.help}</small></Link>)}</div><Card title="Acciones rápidas"><div className="actions quick-actions">{quickActions}</div></Card><div className="dashboard-grid">{children}</div></section>;
}

function kpiCard(label: string, value: any, period: string, help: string, route: string, tone: Severity = 'info') {
  return { label, value, period, help, route, tone, icon: <Gauge {...iconProps} /> };
}

function DashboardList({ title, rows, empty, allRoute }: { title: string; rows: [string, string, Severity, string][]; empty: string; allRoute?: string }) {
  return <Card title={title}>{rows.length ? <div className="compact-list dashboard-list">{rows.map(([head, text, tone, route]) => <article key={`${title}-${head}-${text}`}><Badge tone={tone}>{head}</Badge><p>{text}</p><Link to={route}>Abrir</Link></article>)}</div> : <p className="large-note">{empty}</p>}<Link className="link-button" to={allRoute ?? (rows[0]?.[3] ? rows[0][3].split('?')[0] : '/app/inicio')}>Ver todos</Link></Card>;
}

function SuperadminGuard({ children }: { children: ReactNode }) {
  const { profile } = useAuth();
  if (!isSuperadmin(profile)) return <section className="page"><Card title="No tienes permiso para acceder a esta zona"><p className="form-error"><ShieldAlert size={16} />No tienes permiso para acceder a esta zona</p><Link className="primary" to="/app/inicio">Volver al inicio</Link></Card></section>;
  return <ErrorBoundaryScreen scope="Módulo superadmin">{children}</ErrorBoundaryScreen>;
}

function SuperadminHome() {
  const { data, loading, error, reload } = useLoad(() => superadminService.overview(), [], null as any);
  if (loading || error || !data) return <StateBlock loading={loading} error={error} retry={reload} empty={!data} />;
  const roleCounts = data.roles.map((role: any) => [role.name, data.profiles.filter((profile: any) => profile.profile_roles?.some((item: any) => item.roles?.name === role.name)).length, '/app/superadmin/roles']) as [string, number, string][];
  const openWorkOrders = data.workOrders.filter((row: any) => !['Enviado', 'Cerrado', 'Cancelado'].includes(row.status));
  const pendingChecks = data.checks.filter((row: any) => ['Por realizar', 'En curso'].includes(row.status));
  const kpis = [
    kpiCard('Usuarios totales', data.profiles.length, 'Global', 'Perfiles visibles', '/app/superadmin/usuarios', 'info'),
    kpiCard('Usuarios activos', data.profiles.filter((row: any) => row.active).length, 'Global', 'Activos en profiles', '/app/superadmin/usuarios', 'ok'),
    kpiCard('Usuarios inactivos', data.profiles.filter((row: any) => !row.active).length, 'Global', 'Desactivados en profiles', '/app/superadmin/usuarios', 'warn'),
    kpiCard('Clientes', data.clients.length, 'Global', 'Clientes no eliminados', '/app/superadmin/clientes', 'commercial'),
    kpiCard('Centros', data.sites.length, 'Global', 'Centros no eliminados', '/app/superadmin/centros', 'maintenance'),
    kpiCard('Equipos', data.equipment.length, 'Global', 'Equipos no eliminados', '/app/superadmin/equipos', 'info'),
    kpiCard('Partes abiertos', openWorkOrders.length, 'Global', 'Carga operativa abierta', '/app/superadmin/partes', 'warn'),
    kpiCard('Checks pendientes', pendingChecks.length, 'Global', 'Checks por realizar/en curso', '/app/superadmin/checks', 'danger'),
    kpiCard('Errores sync', 0, 'No configurado', 'Sin incidencias globales registradas', '/app/superadmin/sincronizacion', 'muted'),
  ];
  return <RoleDashboard title="Panel Superadmin / Propietario DMP" subtitle="Gobierno de usuarios, permisos y operaciones de la empresa operadora." kpis={kpis} quickActions={<><Link to="/app/superadmin/usuarios">Gestionar usuarios</Link><Link to="/app/superadmin/usuarios/nuevo">Crear usuario</Link><Link to="/app/superadmin/roles">Roles y permisos</Link><Link to="/app/superadmin/plantillas">Plantillas de checks</Link><Link to="/app/superadmin/auditoria">Auditoría</Link><Link to="/app/modulos/administracion">Datos de empresa</Link><Link to="/app/superadmin/clientes">Clientes</Link><Link to="/app/superadmin/partes">Partes</Link></>}><InteractiveBars title="Usuarios por rol" values={roleCounts.length ? roleCounts : [['Sin roles', 0, '/app/superadmin/roles']]} /><DashboardList title="Últimos usuarios creados" rows={data.profiles.slice(0, 8).map((profile: any) => [fullName(profile) || profile.email, `${profile.email} · ${profile.active ? 'Activo' : 'Inactivo'} · ${rolesText(profile)} · ${profile.primary_area}`, profile.active ? 'ok' : 'warn', '/app/superadmin/usuarios'])} empty="Sin registros" /><DashboardList title="Última actividad relevante" rows={[...data.activity, ...data.audit].slice(0, 8).map((item: any) => [item.action ?? item.operation ?? 'Evento', `${item.entity_type ?? item.table_name ?? 'Sistema'} · ${formatDate(item.created_at ?? item.changed_at)}`, 'info', '/app/superadmin/auditoria'])} empty="Sin registros" /><Card title="Sincronización técnica"><p className="large-note">Los cambios pendientes de cada dispositivo se revisan desde Sincronización.</p></Card><Card title="Seguridad de contraseñas"><p className="large-note">Las contraseñas no se muestran ni se leen. Gestiona las altas y restablecimientos desde el canal autorizado de administración.</p></Card></RoleDashboard>;
}

function SuperadminUsers() {
  const { data, loading, error, reload } = useLoad(() => superadminService.users(), [], [] as any[]);
  const [editing, setEditing] = useState<any | null>(null);
  const [message, setMessage] = useState('');
  const [search, setSearch] = useState('');
  const [area, setArea] = useState('todas');
  const [active, setActive] = useState('todos');
  const rows = data.filter((user) => {
    const haystack = `${user.first_name ?? ''} ${user.last_name ?? ''} ${user.email ?? ''} ${user.phone ?? ''} ${user.auth_user_id ?? ''} ${user.company_id ?? ''} ${user.primary_area ?? ''} ${rolesText(user)}`.toLowerCase();
    const areaOk = area === 'todas' || normalizeArea(user.primary_area) === area;
    const activeOk = active === 'todos' || (active === 'activos' ? user.active : !user.active);
    return haystack.includes(search.toLowerCase()) && areaOk && activeOk;
  });
  return <section className="page"><Breadcrumb items={['Propietario DMP', 'Usuarios']} /><div className="page-head"><div><h2>Usuarios</h2><p>Perfiles de la empresa operadora. No se muestran ni se guardan contraseñas.</p></div><Link className="primary" to="/app/superadmin/users/new">Crear usuario</Link></div>{message && <p className="success-note">{message}</p>}<div className="filters local-filters"><label><Search size={16} /><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Buscar por nombre, email, identificador o rol..." /></label><FormSelect label="Área" value={area} onChange={setArea} options={[{ value: 'todas', label: 'Todas' }, ...areaOptions().map((item) => ({ value: normalizeArea(item), label: areaLabel(item) }))]} /><FormSelect label="Estado" value={active} onChange={setActive} options={[{ value: 'todos', label: 'Todos' }, { value: 'activos', label: 'Activos' }, { value: 'inactivos', label: 'Inactivos' }]} /></div><StateBlock loading={loading} error={error} retry={reload} empty={!rows.length}><div className="table-card"><table><thead><tr><th>Nombre</th><th>Apellidos</th><th>Email</th><th>Área/rol principal</th><th>Activo</th><th>Identificador de acceso</th><th>Fechas</th><th>Acciones</th></tr></thead><tbody>{rows.map((user: any) => <tr key={user.id} className={isArchivedRecord('profiles', user) ? 'archived-row' : ''}><td>{user.first_name}<span>{rolesText(user)}</span></td><td>{user.last_name}</td><td>{user.email}</td><td>{areaLabel(user.primary_area)}</td><td>{user.active ? 'Activo' : 'Inactivo'}</td><td><small>{user.auth_user_id ?? 'Sin enlazar'}</small></td><td>{formatDate(user.created_at)}<span>Actualizado: {formatDate(user.updated_at)}</span>{user.deleted_at && <span>Eliminado: {formatDate(user.deleted_at)}</span>}</td><td><div className="row-actions"><button onClick={() => setEditing(user)}>Ver / editar</button><LifecycleActionPanel entity="profiles" record={user} onChanged={() => { setMessage('Operacion de ciclo de vida registrada.'); reload(); }} /></div></td></tr>)}</tbody></table></div></StateBlock>{editing && <SuperadminProfileForm initial={editing} onClose={() => setEditing(null)} onSaved={() => { setEditing(null); reload(); }} />}</section>;
}

function SuperadminUserCreate() {
  const navigate = useNavigate();
  return <section className="page"><Breadcrumb items={['Propietario DMP', 'Crear usuario']} /><Hero title="Crear usuario" subtitle="Crea el perfil y vincula su identificador de acceso." tone="info" /><SuperadminProfileForm onClose={() => navigate('/app/superadmin/usuarios')} onSaved={() => navigate('/app/superadmin/usuarios')} /></section>;
}

function SuperadminProfileForm({ initial, onClose, onSaved }: any) {
  const [values, setValues] = useState<Record<string, any>>({ first_name: '', last_name: '', email: '', phone: '', primary_area: 'SAT', active: true, auth_user_id: '', roles: initial ? rolesList(initial) : ['SAT'], ...initial });
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const set = (key: string, value: any) => setValues((current) => ({ ...current, [key]: value }));
  const submit = async (event: FormEvent) => {
    event.preventDefault();
    setSaving(true); setError('');
    try {
      const roles = normalizedRoleNames(values.primary_area, values.roles?.length ? values.roles : [values.primary_area]);
      const payload = { first_name: values.first_name, last_name: values.last_name, email: values.email, phone: values.phone || null, primary_area: roles.includes('SAT') ? 'SAT' : values.primary_area, active: values.active === true || values.active === 'true', auth_user_id: values.auth_user_id || null };
      await superadminService.saveProfileWithRoles(initial?.id ?? null, payload, roles);
      onSaved?.();
    } catch (err) { console.error(err); setError(err instanceof Error ? err.message : 'No se ha podido guardar el usuario.'); }
    finally { setSaving(false); }
  };
  const toggleRole = (role: string) => setValues((current) => ({ ...current, roles: toggleExclusiveRole(current.roles ?? [], role), primary_area: role === 'SAT' || role === 'Comercial' ? role : current.primary_area }));
  useEffect(() => { const roles = selectPrimaryRole(values.roles ?? [], values.primary_area); if (roles.join('|') !== (values.roles ?? []).join('|')) set('roles', roles); }, [values.primary_area, (values.roles ?? []).join('|')]);
  return <ModalForm title={initial?.id ? 'Editar usuario' : 'Crear usuario'} onClose={onClose} onSubmit={submit} saving={saving} error={error} submitLabel={initial?.id ? 'Guardar usuario' : 'Crear perfil'}><p className="large-note">No se guarda ni se muestra ninguna contraseña. Indica el identificador de acceso cuando el usuario ya esté dado de alta.</p><p className="large-note">SAT y Comercial son incompatibles en el mismo perfil. Al seleccionar uno se desmarca el otro.</p><div className="form-grid"><label>Nombre *<input value={values.first_name ?? ''} onChange={(event) => set('first_name', event.target.value)} required /></label><label>Apellidos *<input value={values.last_name ?? ''} onChange={(event) => set('last_name', event.target.value)} required /></label><label>Email *<input type="email" value={values.email ?? ''} onChange={(event) => set('email', event.target.value)} required /></label><label>Teléfono<input value={values.phone ?? ''} onChange={(event) => set('phone', event.target.value)} /></label><FormSelect label="Área/rol principal" value={values.primary_area} onChange={(value) => { set('primary_area', value); if (!values.roles.includes(value)) set('roles', [...values.roles, value]); }} required options={areaOptions().map((value) => ({ value, label: areaLabel(value) }))} /><FormSelect label="Estado" value={String(values.active)} onChange={(value) => set('active', value)} options={[{ value: 'true', label: 'Activo' }, { value: 'false', label: 'Inactivo' }]} /><label>Identificador de acceso<input value={values.auth_user_id ?? ''} onChange={(event) => set('auth_user_id', event.target.value)} placeholder="Identificador del usuario" /></label></div><Card title="Roles adicionales"><div className="component-select">{areaOptions().map((role) => <label key={role}><input type="checkbox" checked={values.roles.includes(role)} onChange={() => toggleRole(role)} /> {areaLabel(role)}</label>)}</div></Card><Card title="Contraseñas"><p className="large-note">El acceso Auth debe crearse o invitarse desde backend seguro. No se usa ninguna clave de servicio en el navegador.</p></Card></ModalForm>;
}

function SuperadminSettings() {
  const roles = useLoad(() => superadminService.roles(), [], [] as any[]);
  return <section className="page"><Breadcrumb items={['Propietario DMP', 'Configuración']} /><Hero title="Configuración superadmin" subtitle="Ajustes operativos de usuarios, roles y datos de empresa." tone="info" /><div className="grid half"><Card title="Roles disponibles"><InfoGrid items={[[ 'Roles', roles.data.map((role: any) => role.name).join(', ') || '-' ]]} /></Card><Card title="Acciones de gobierno"><div className="actions"><Link to="/app/superadmin/usuarios">Gestionar usuarios</Link><Link to="/app/superadmin/roles">Revisar permisos</Link><Link to="/app/superadmin/plantillas">Plantillas de checks</Link><Link to="/app/modulos/administracion">Datos de empresa</Link><Link to="/app/superadmin/auditoria">Auditoría</Link></div>{roles.error && <p className="form-error">{roles.error}</p>}</Card></div></section>;
}

function SuperadminRoles() {
  const permissions = ['ver clientes','crear clientes','editar clientes','ver centros','crear centros','editar centros','ver equipos','crear equipos','editar equipos','ver partes','crear partes','editar partes','asignar técnicos','ver checks','crear checks','ejecutar checks','sincronizar trabajo técnico','ver facturación','ver documentación','gestionar usuarios','gestionar plantillas','ver auditoría'];
  const roles = ['superadmin','Gerencia','SAT','Comercial','Oficina','Tecnico'];
  return <section className="page"><Breadcrumb items={['Propietario DMP', 'Roles y permisos']} /><Hero title="Roles y permisos" subtitle="Resumen de accesos por rol." tone="info" /><Card title="Matriz de permisos"><div className="table-card slim"><table><thead><tr><th>Rol</th>{permissions.map((permission) => <th key={permission}>{permission}</th>)}</tr></thead><tbody>{roles.map((role) => <tr key={role}><td>{role === 'superadmin' ? 'Propietario DMP' : role}</td>{permissions.map((permission) => <td key={`${role}-${permission}`}>{permissionForRole(role, permission) ? 'Sí' : 'No'}</td>)}</tr>)}</tbody></table></div><p className="large-note">Los permisos se aplican según el rol activo.</p></Card></section>;
}

function SuperadminTemplates() {
  const { workspace } = useAuth();
  const isPlatformScope = workspace === 'superadmin';
  const templateScope = undefined;
  const { data, loading, error, reload } = useLoad(() => superadminService.templates(templateScope), [templateScope], [] as any[]);
  const [form, setForm] = useState<any>(null);
  const [message, setMessage] = useState('');
  const [actionError, setActionError] = useState('');
  const run = async (operation: () => Promise<any>, ok: string) => { try { setActionError(''); await operation(); setMessage(ok); reload(); } catch (err) { console.error(err); setActionError(err instanceof Error ? err.message : 'No se ha podido completar la operación.'); } };
  const toggle = (template: any) => run(() => superadminService.toggleTemplate(template.id, !template.active), template.active ? 'Plantilla desactivada.' : 'Plantilla activada.');
  const duplicate = (template: any) => run(() => superadminService.duplicateTemplate(template), 'Plantilla duplicada con sus bloques e ítems.');
  return <section className="page"><Breadcrumb items={[(isPlatformScope ? 'Propietario DMP' : 'SAT'), 'Plantillas de checks']} /><div className="page-head"><div><h2>Plantillas de checks</h2><p>Crear, editar, duplicar, ordenar y activar plantillas disponibles para la empresa.</p></div><button className="primary" onClick={() => setForm({ type: 'template', initial: { active: true, version: '1.0' } })}>Crear plantilla</button></div>{message && <p className="success-note">{message}</p>}{actionError && <p className="form-error">{actionError}</p>}<StateBlock loading={loading} error={error} retry={reload} empty={!data.length}><div className="grid half">{data.map((template: any) => { const sections = [...(template.check_template_sections ?? [])].sort(byTemplatePosition); return <Card key={template.id} title={template.name} action={<button onClick={() => toggle(template)}>{template.active ? 'Desactivar' : 'Activar'}</button>}><InfoGrid items={[[ 'Tipo compatible', template.equipment_types?.name ?? 'Global' ], [ 'Versión', template.version ], [ 'Estado', template.active ? 'Activo' : 'Inactivo' ], [ 'Bloques', String(sections.length) ], [ 'Ítems', String(sections.reduce((sum: number, section: any) => sum + (section.check_template_items?.length ?? 0), 0)) ], [ 'Creación', formatDate(template.created_at) ], [ 'Última modificación', formatDate(template.updated_at) ]]} /><div className="actions"><button onClick={() => setForm({ type: 'template', initial: template })}>Editar plantilla</button><button onClick={() => duplicate(template)}>Duplicar plantilla</button><button onClick={() => setForm({ type: 'section', template, initial: { position: sections.length + 1 } })}>Añadir bloque</button></div><div className="template-builder">{sections.map((section: any, index: number) => { const items = [...(section.check_template_items ?? [])].sort(byTemplatePosition); return <article key={section.id} className="template-section"><header><strong>{section.position}. {section.title}</strong><div className="row-actions"><button onClick={() => setForm({ type: 'section', template, initial: section })}>Editar</button><button disabled={index === 0} onClick={() => run(() => superadminService.reorderSections(moveItem(sections, index, index - 1)), 'Bloques reordenados.')}>Subir</button><button disabled={index === sections.length - 1} onClick={() => run(() => superadminService.reorderSections(moveItem(sections, index, index + 1)), 'Bloques reordenados.')}>Bajar</button><button onClick={() => window.confirm('Eliminar este bloque solo si no tiene resultados asociados?') && run(() => superadminService.deleteSection(section.id), 'Bloque eliminado si no tenía resultados vinculados.')}>Eliminar</button></div></header><div className="template-items">{items.map((item: any, itemIndex: number) => <div key={item.id} className="template-item"><span>{item.position}. {item.title} · {item.component} · {item.mandatory ? 'Obligatorio' : 'Opcional'}</span><div className="row-actions"><button onClick={() => setForm({ type: 'item', section, initial: item })}>Editar</button><button disabled={itemIndex === 0} onClick={() => run(() => superadminService.reorderItems(moveItem(items, itemIndex, itemIndex - 1)), 'Ítems reordenados.')}>Subir</button><button disabled={itemIndex === items.length - 1} onClick={() => run(() => superadminService.reorderItems(moveItem(items, itemIndex, itemIndex + 1)), 'Ítems reordenados.')}>Bajar</button><button onClick={() => window.confirm('Eliminar este ítem solo si no tiene resultados asociados?') && run(() => superadminService.deleteItem(item.id), 'Ítem eliminado si no tenía resultados vinculados.')}>Eliminar</button></div></div>)}<button onClick={() => setForm({ type: 'item', section, initial: { position: items.length + 1, mandatory: true } })}>Añadir ítem</button></div></article>; })}</div></Card>; })}</div></StateBlock>{form?.type === 'template' && <TemplateForm initial={form.initial} onClose={() => setForm(null)} onSaved={() => { setForm(null); reload(); }} />}{form?.type === 'section' && <TemplateSectionForm template={form.template} initial={form.initial} onClose={() => setForm(null)} onSaved={() => { setForm(null); reload(); }} />}{form?.type === 'item' && <TemplateItemForm section={form.section} initial={form.initial} onClose={() => setForm(null)} onSaved={() => { setForm(null); reload(); }} />}</section>;
}

function TemplateForm({ initial, onClose, onSaved }: any) {
  const types = useLoad(() => equipmentService.types(initial?.company_id), [initial?.company_id], [] as any[]);
  const [values, setValues] = useState<Record<string, any>>(initial);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const set = (key: string, value: any) => setValues((current) => ({ ...current, [key]: value }));
  const submit = async (event: FormEvent) => { event.preventDefault(); setSaving(true); setError(''); try { const result = values.id ? await superadminService.updateTemplate(values.id, values) : await superadminService.createTemplate(values); onSaved(result); } catch (err) { console.error(err); setError(err instanceof Error ? err.message : 'No se ha podido guardar la plantilla.'); } finally { setSaving(false); } };
  return <ModalForm title={values.id ? 'Editar plantilla' : 'Crear plantilla'} onClose={onClose} onSubmit={submit} saving={saving} error={error}><label>Nombre *<input value={values.name ?? ''} onChange={(event) => set('name', event.target.value)} required /></label><label>Versión *<input value={values.version ?? '1.0'} onChange={(event) => set('version', event.target.value)} required /></label><FormSelect label="Tipo compatible" value={values.equipment_type_id} onChange={(value) => set('equipment_type_id', value)} options={types.data.map((type) => ({ value: type.id, label: type.name }))} loading={types.loading} /><label className="checkbox-line"><input type="checkbox" checked={Boolean(values.active)} onChange={(event) => set('active', event.target.checked)} /> Activa</label></ModalForm>;
}

function TemplateSectionForm({ template, initial, onClose, onSaved }: any) {
  return <EntityForm title={initial?.id ? 'Editar bloque' : 'Añadir bloque'} fields={[[ 'title', 'Título', true ], [ 'position', 'Orden', true ]]} initial={initial} onClose={onClose} onSubmit={(values: any) => initial?.id ? superadminService.updateSection(initial.id, values) : superadminService.createSection(template.id, values)} onSaved={onSaved} />;
}

function TemplateItemForm({ section, initial, onClose, onSaved }: any) {
  const [values, setValues] = useState<Record<string, any>>(initial);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const set = (key: string, value: any) => setValues((current) => ({ ...current, [key]: value }));
  const submit = async (event: FormEvent) => { event.preventDefault(); setSaving(true); setError(''); try { const result = values.id ? await superadminService.updateItem(values.id, values) : await superadminService.createItem(section.id, values); onSaved(result); } catch (err) { console.error(err); setError(err instanceof Error ? err.message : 'No se ha podido guardar el ítem.'); } finally { setSaving(false); } };
  return <ModalForm title={values.id ? 'Editar ítem' : 'Añadir ítem'} onClose={onClose} onSubmit={submit} saving={saving} error={error}><label>Título *<input value={values.title ?? ''} onChange={(event) => set('title', event.target.value)} required /></label><label>Componente<input value={values.component ?? ''} onChange={(event) => set('component', event.target.value)} placeholder="Si se deja vacío se usa el título" /></label><label>Orden *<input type="number" min="1" value={values.position ?? ''} onChange={(event) => set('position', event.target.value)} required /></label><label className="checkbox-line"><input type="checkbox" checked={values.mandatory !== false} onChange={(event) => set('mandatory', event.target.checked)} /> Obligatorio</label></ModalForm>;
}

