function SuperadminEquipmentDetail({ id }: { id: string }) {
  const { data, loading, error, reload } = useLoad(() => equipmentService.get(id), [id], null as any);
  const history = useLoad(() => equipmentService.history(id), [id], [] as any[]);
  const [mode, setMode] = useState<'edit' | 'component' | 'work' | 'check' | null>(null);
  if (loading || error || !data) return <StateBlock loading={loading} error={error} retry={reload} empty={!data} />;
  return <section className="page"><BackButton /><Hero title={`${data.code} · ${data.equipment_types?.name ?? 'Equipo'}`} subtitle={`${data.clients?.legal_name ?? ''} · ${data.sites?.name ?? ''}`} tone={severityForStatus(data.status)} /><div className="actions"><button onClick={() => setMode('edit')}>Modificar equipo</button><button onClick={() => setMode('component')}>Añadir componente</button><button onClick={() => setMode('work')}>Crear parte</button><button onClick={() => setMode('check')}>Crear check</button></div><Card title="Identificación"><InfoGrid items={[[ 'Código', data.code ], [ 'Cliente', data.clients?.legal_name ?? '-' ], [ 'Centro', data.sites?.name ?? '-' ], [ 'Ubicación', data.internal_location ?? '-' ], [ 'Fabricante', data.brand ?? '-' ], [ 'Modelo', data.model ?? '-' ], [ 'Serie', data.serial_number ?? '-' ], [ 'Estado', displayStatus(data.status) ], [ 'Criticidad', displayStatus(data.criticality) ]]} /></Card><div className="grid half"><Card title="Componentes"><CompactRows rows={(data.equipment_components ?? []).map((component: any) => [component.component_type, `${component.brand ?? '-'} ${component.model ?? ''} · ${component.status}`, severityForStatus(component.status), `/app/superadmin/equipos/${id}`])} empty="Sin componentes." /></Card><Card title="Historial"><CompactRows rows={history.data.map((item: any) => [displayStatus(item.event_type), `${formatDate(item.event_at)} · ${item.summary ?? ''} · ${item.detail ?? ''}`, severityForStatus(item.detail), item.event_type === 'parte' ? '/app/superadmin/partes' : `/app/superadmin/equipos/${id}`])} empty="Sin historial." /></Card></div>{mode === 'edit' && <EquipmentForm initial={data} onClose={() => setMode(null)} onSaved={() => { setMode(null); reload(); }} />}{mode === 'component' && <ComponentForm equipmentId={data.id} onClose={() => setMode(null)} onSaved={() => { setMode(null); reload(); }} />}{mode === 'work' && <WorkOrderForm initial={{ company_id: data.company_id, client_id: data.client_id, site_id: data.site_id, main_equipment_id: data.id }} onClose={() => setMode(null)} onSaved={() => { setMode(null); reload(); }} />}{mode === 'check' && <CheckForm initial={{ company_id: data.company_id, equipment_id: data.id }} onClose={() => setMode(null)} onSaved={() => { setMode(null); reload(); }} />}</section>;
}

function SuperadminWorkOrderDetail({ id }: { id: string }) {
  const { data, loading, error, reload } = useLoad(() => workOrdersService.get(id), [id], null as any);
  const [mode, setMode] = useState<'edit' | 'assign' | 'check' | null>(null);
  const [message, setMessage] = useState('');
  const [actionError, setActionError] = useState('');
  if (loading || error || !data) return <StateBlock loading={loading} error={error} retry={reload} empty={!data} />;
  const previous = previousWorkOrderStatus(data.status);
  const advance = async () => { try { setActionError(''); await workOrdersService.changeStatus(data.id, nextWorkOrderStatus(data.status), 'Cambio operativo desde Superadmin'); setMessage('Estado actualizado.'); reload(); } catch (err) { console.error(err); setActionError(err instanceof Error ? err.message : 'No se ha podido cambiar el estado.'); } };
  const goBack = async () => { const reason = window.prompt('Motivo de la corrección de estado'); if (!reason) return; try { setActionError(''); await workOrdersService.changeStatus(data.id, previous!, reason, true); setMessage('Estado anterior restaurado.'); reload(); } catch (err) { console.error(err); setActionError(err instanceof Error ? err.message : 'No se ha podido restaurar el estado.'); } };
  return <section className="page"><BackButton /><Hero title={`${data.code} · ${data.title}`} subtitle={`${data.clients?.legal_name ?? ''} · ${data.sites?.name ?? ''}`} tone={severityForStatus(data.status)} /><div className="actions"><button onClick={() => setMode('edit')}>Modificar parte</button><button onClick={() => setMode('assign')}>Asignar técnico</button><WorkOrderStatusSelector workOrder={data} onChanged={() => { setMessage("Estado actualizado."); reload(); }} onError={setActionError} /><button onClick={() => setMode('check')}>Crear check</button>{data.client_id && <Link to={`/app/superadmin/clientes/${data.client_id}`}>Abrir cliente</Link>}{data.site_id && <Link to={`/app/superadmin/centros/${data.site_id}`}>Abrir centro</Link>}{data.main_equipment_id && <Link to={`/app/superadmin/equipos/${data.main_equipment_id}`}>Abrir equipo</Link>}</div>{message && <p className="success-note">{message}</p>}{actionError && <p className="form-error">{actionError}</p>}<Card title="Detalle del parte"><InfoGrid items={[[ 'Estado', displayStatus(data.status) ], [ 'Prioridad', displayStatus(data.priority) ], [ 'Cliente', data.clients?.legal_name ?? '-' ], [ 'Centro', data.sites?.name ?? '-' ], [ 'Equipo', data.primary_equipment?.code ?? '-' ], [ 'Fecha', data.scheduled_date ?? '-' ], [ 'Hora', data.scheduled_time ?? '-' ], [ 'Origen', data.origin ?? '-' ], [ 'Presupuesto origen', data.quotes?.code ?? '-' ], [ 'Descripción', data.description ?? '-' ]]} /></Card><Card title="Asignaciones, checks y relaciones"><CompactRows rows={[...(data.assignments ?? []).map((item: any) => [fullName(item.profiles), `${item.assignment_date ?? '-'} · ${item.planned_start_time ?? 'Sin hora'} · ${displayStatus(item.status)}`, 'info', `/app/superadmin/partes/${data.id}`]), ...(data.checks ?? []).map((check: any) => [check.code, `${displayStatus(check.status)} · ${displayStatus(check.global_result)}`, severityForStatus(check.global_result), `/app/superadmin/checks/${check.id}`]), ...(data.deficiencies ?? []).map((def: any) => [def.code, `${displayStatus(def.severity)} · ${displayStatus(def.status)}`, severityForPriority(def.severity), '/app/deficiencias'])]} empty="Sin asignaciones ni checks vinculados." /></Card>{mode === 'edit' && <WorkOrderForm initial={data} onClose={() => setMode(null)} onSaved={() => { setMode(null); reload(); }} />}{mode === 'assign' && <AssignmentForm workOrderId={data.id} companyId={data.company_id} onClose={() => setMode(null)} onSaved={() => { setMode(null); reload(); }} />}{mode === 'check' && <CheckForm initial={{ company_id: data.company_id, work_order_id: data.id, equipment_id: data.main_equipment_id }} onClose={() => setMode(null)} onSaved={() => { setMode(null); reload(); }} />}</section>;
}

function OperationalProfilePage({ profileId, role }: { profileId: string; role: 'Tecnico' | 'Comercial' }) {
  const { profile } = useAuth();
  const [assigning, setAssigning] = useState(false);
  const people = useLoad(() => role === 'Tecnico' ? profilesService.listTechnicians() : profilesService.listCommercials(), [role], [] as any[]);
  const works = useLoad(() => workOrdersService.listWithAssignments(), [], [] as any[]);
  const checks = useLoad(() => checksService.pending(), [], [] as any[]);
  const person = people.data.find((item) => item.id === profileId);
  const canManage = canManageWorkOrderAssignments(profile);
  const assignedWorks = works.data.filter((work: any) => role === 'Tecnico' ? (work.assignments ?? []).some((item: any) => item.technician_id === profileId && !item.deleted_at) || work.main_technician_id === profileId : work.current_responsible_id === profileId || work.created_by === profileId || work.created_by_name === fullName(person));
  const assignedChecks = checks.data.filter((check: any) => check.technician_id === profileId || check.technician_name === fullName(person));
  if (people.loading || works.loading || checks.loading) return <StateBlock loading retry={() => { people.reload(); works.reload(); checks.reload(); }} empty={false} />;
  if (people.error || works.error || checks.error || !person) return <StateBlock loading={false} error={people.error || works.error || checks.error || 'No se ha encontrado la ficha solicitada.'} retry={() => { people.reload(); works.reload(); checks.reload(); }} empty={false} />;
  const activeToday = assignedWorks.filter((work: any) => work.scheduled_date === new Date().toISOString().slice(0, 10));
  const openWorks = assignedWorks.filter((work: any) => !['Enviado','Cerrado','Cancelado'].includes(work.status));
  return <section className="page"><BackButton /><Hero title={`${role === 'Tecnico' ? 'Ficha técnico' : 'Ficha comercial'} · ${fullName(person)}`} subtitle={`${person.email ?? '-'} · ${person.phone ?? '-'} · ${person.active ? 'Activo' : 'Inactivo'}`} tone={role === 'Tecnico' ? 'maintenance' : 'commercial'} /><div className="actions">{canManage && <button className="primary" onClick={() => setAssigning(true)}>{role === 'Tecnico' ? 'Asignar parte' : 'Asignar visita/parte'}</button>}<Link to="/app/partes">Ver partes</Link><Link to="/app/checks">Ver checks</Link></div><div className="stats-grid"><Card title="Datos"><InfoGrid items={[[ 'Nombre', fullName(person) ], [ 'Rol', areaLabel(person.primary_area) ], [ 'Email', person.email ?? '-' ], [ 'Teléfono', person.phone ?? '-' ], [ 'Estado', person.active ? 'Activo' : 'Inactivo' ]]} /></Card><Card title="Carga de trabajo"><InfoGrid items={[[ 'Partes asignados', assignedWorks.length ], [ 'Abiertos', openWorks.length ], [ 'Hoy', activeToday.length ], [ 'Checks pendientes', assignedChecks.length ], [ 'Disponibilidad', !person.active ? 'Fuera de servicio' : openWorks.some((work: any) => ['En desplazamiento','En intervencion','Pausado'].includes(work.status)) ? 'Ocupado' : 'Disponible' ]]} /></Card></div><Card title={role === 'Tecnico' ? 'Partes asignados' : 'Visitas y partes comerciales'}><div className="compact-list">{assignedWorks.map((work: any) => <article key={work.id}><Badge tone={severityForStatus(work.status)}>{work.code}</Badge><p>{work.title} · {work.client_name ?? '-'} · {displayStatus(work.status)} · {work.scheduled_date ?? 'Sin fecha'}</p><div className="row-actions"><Link to={`/app/partes/${work.id}`}>Abrir parte</Link>{canManage && <Link to={`/app/partes/${work.id}`}>Gestionar asignaciones</Link>}</div></article>)}{!assignedWorks.length && <p className="large-note">Sin partes asignados.</p>}</div></Card><Card title="Checks asignados"><CompactRows rows={assignedChecks.map((check: any) => [check.code, `${check.equipment_code ?? 'Equipo'} · ${displayStatus(check.status)} · ${displayStatus(check.global_result)}`, severityForStatus(check.global_result), `/app/checks/${check.id}`])} empty="Sin checks pendientes." /></Card>{assigning && <OperationalAssignForm role={role} profileId={profileId} workOrders={works.data} onClose={() => setAssigning(false)} onSaved={() => { setAssigning(false); works.reload(); }} />}</section>;
}

function OperationalAssignForm({ role, profileId, workOrders, onClose, onSaved }: any) {
  const [values, setValues] = useState<Record<string, any>>({ assignment_date: new Date().toISOString().slice(0, 10), role: 'Principal' });
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const candidates = workOrders.filter((work: any) => !['Enviado','Cerrado','Cancelado'].includes(work.status));
  const submit = async (event: FormEvent) => {
    event.preventDefault(); setSaving(true); setError('');
    try {
      if (role === 'Tecnico') await workOrdersService.assign(values.work_order_id, profileId, values.assignment_date, values.planned_start_time || null, values.planned_end_time || null, values.role || 'Principal');
      else await workOrdersService.assignCommercial(values.work_order_id, profileId);
      onSaved?.();
    } catch (err) { setError(err instanceof Error ? err.message : 'No se ha podido asignar.'); }
    finally { setSaving(false); }
  };
  return <ModalForm title={role === 'Tecnico' ? 'Asignar parte a técnico' : 'Asignar visita/parte a comercial'} onClose={onClose} onSubmit={submit} saving={saving} error={error} submitLabel="Asignar"><FormSelect label="Parte / visita" value={values.work_order_id} onChange={(value) => setValues({ ...values, work_order_id: value })} required options={candidates.map((work: any) => ({ value: work.id, label: `${work.code} · ${work.title} · ${work.client_name ?? '-'}` }))} />{role === 'Tecnico' && <div className="form-grid"><label>Fecha *<input type="date" value={values.assignment_date ?? ''} onChange={(event) => setValues({ ...values, assignment_date: event.target.value })} required /></label><label>Hora inicio<input type="time" value={values.planned_start_time ?? ''} onChange={(event) => setValues({ ...values, planned_start_time: event.target.value })} /></label><label>Hora fin<input type="time" value={values.planned_end_time ?? ''} onChange={(event) => setValues({ ...values, planned_end_time: event.target.value })} /></label><FormSelect label="Rol" value={values.role} onChange={(value) => setValues({ ...values, role: value })} options={['Principal','Apoyo'].map((value) => ({ value, label: value }))} /></div>}</ModalForm>;
}

function GlobalSearch({ query, setQuery }: { query: string; setQuery: (value: string) => void }) {
  const navigate = useNavigate();
  const { workspace } = useAuth();
  const requestRef = useRef(0);
  const [data, setData] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [searchError, setSearchError] = useState('');
  const trimmed = query.trim();
  useEffect(() => {
    const requestId = ++requestRef.current;
    if (!trimmed) { setData([]); setLoading(false); setSearchError(''); return; }
    setLoading(true); setSearchError('');
    const timer = window.setTimeout(async () => {
      try {
        const rows = workspace === 'tecnico' ? await searchService.technician(trimmed) : await searchService.global(trimmed);
        if (requestRef.current === requestId) setData(rows);
      } catch (error) {
        console.error('No se ha podido ejecutar la búsqueda global', error);
        if (requestRef.current === requestId) { setData([]); setSearchError(error instanceof Error ? error.message : 'No se ha podido buscar.'); }
      } finally {
        if (requestRef.current === requestId) setLoading(false);
      }
    }, 250);
    return () => window.clearTimeout(timer);
  }, [trimmed, workspace]);
  const open = (item: any) => { setQuery(''); navigate(item.route); };
  return <div className="search-wrap"><label className="search"><Search size={17} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder={workspace === 'tecnico' ? 'Buscar mis trabajos y checks...' : 'Buscar cliente, equipo, expediente, parte...'} /></label>{trimmed && <div className="search-results">{loading && <p>Buscando...</p>}{!loading && searchError && <p className="form-error">{searchError}</p>}{!loading && !searchError && data.slice(0, 8).map((item) => <button key={`${item.route}-${item.id}`} onClick={() => open(item)}><Badge tone="info">{item.kind ?? 'Resultado'}</Badge><span>{item.title}</span><small>{item.subtitle ?? 'Registro'}</small></button>)}{!loading && !searchError && !data.length && <p>Sin resultados.</p>}</div>}</div>;
}

function SuperadminUserForm({ initial, onClose, onSaved }: any) {
  const roleOptions = ['superadmin','Gerencia','SAT','Comercial','Oficina','Tecnico'];
  const [values, setValues] = useState<Record<string, any>>({ first_name: '', last_name: '', email: '', phone: '', primary_area: 'SAT', active: true, roles: initial ? rolesList(initial) : ['SAT'], invitation_mode: 'invite', ...initial });
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const set = (key: string, value: any) => setValues((current) => ({ ...current, [key]: value }));
  const toggleRole = (role: string) => setValues((current) => ({ ...current, roles: toggleExclusiveRole(current.roles ?? [], role), primary_area: role === 'SAT' || role === 'Comercial' ? role : current.primary_area }));
  useEffect(() => { const roles = selectPrimaryRole(values.roles ?? [], values.primary_area); if (roles.join('|') !== (values.roles ?? []).join('|')) set('roles', roles); }, [values.primary_area, (values.roles ?? []).join('|')]);
  const submit = async (event: FormEvent) => {
    event.preventDefault();
    setSaving(true); setError('');
    try {
      const profilePayload = { first_name: values.first_name, last_name: values.last_name, email: values.email, phone: values.phone || null, primary_area: values.primary_area, active: values.active === true || values.active === 'true', auth_user_id: values.auth_user_id || null };
      await superadminService.saveProfileWithRoles(initial?.id ?? null, profilePayload, values.roles?.length ? values.roles : [values.primary_area]);
      onSaved?.();
    } catch (err) { setError(err instanceof Error ? err.message : 'No se ha podido guardar el usuario.'); }
    finally { setSaving(false); }
  };
  return <ModalForm title={initial?.id ? 'Editar usuario' : 'Crear usuario'} onClose={onClose} onSubmit={submit} saving={saving} error={error} submitLabel={initial?.id ? 'Guardar usuario' : 'Crear perfil'}><p className="large-note">No se guarda ni se muestra ninguna contraseña. Indica el identificador de acceso cuando el usuario ya esté dado de alta.</p><p className="large-note">SAT y Comercial son incompatibles en el mismo perfil. Al seleccionar uno se desmarca el otro.</p><div className="form-grid"><label>Nombre *<input value={values.first_name ?? ''} onChange={(event) => set('first_name', event.target.value)} required /></label><label>Apellidos *<input value={values.last_name ?? ''} onChange={(event) => set('last_name', event.target.value)} required /></label><label>Email *<input type="email" value={values.email ?? ''} onChange={(event) => set('email', event.target.value)} required /></label><label>Teléfono<input value={values.phone ?? ''} onChange={(event) => set('phone', event.target.value)} /></label><label>Identificador de acceso<input value={values.auth_user_id ?? ''} onChange={(event) => set('auth_user_id', event.target.value)} placeholder="Identificador del usuario" /></label><FormSelect label="Rol principal" value={values.primary_area} onChange={(value) => set('primary_area', value)} required options={roleOptions.map((value) => ({ value, label: value === 'superadmin' ? 'Propietario DMP' : value }))} /><FormSelect label="Estado" value={String(values.active)} onChange={(value) => set('active', value)} options={[{ value: 'true', label: 'Activo' }, { value: 'false', label: 'Inactivo' }]} /></div><Card title="Roles adicionales"><div className="component-select">{roleOptions.map((role) => <label key={role}><input type="checkbox" checked={values.roles.includes(role)} onChange={() => toggleRole(role)} /> {role === 'superadmin' ? 'Propietario DMP' : role}</label>)}</div></Card><Card title="Vinculaciones"><p className="large-note">Vincula el perfil con su ficha de técnico o comercial cuando corresponda. Los roles seleccionados determinan qué áreas puede usar.</p></Card><p className="state-warning"><ShieldAlert size={16} />Contraseña protegida. No se mostrará después de crear, no se guarda en tablas públicas y no se registra en consola.</p></ModalForm>;
}

function ClientForm({ title, initial, onClose, onSaved }: any) { const fields = [['legal_name','Razón social',true],['trade_name','Nombre comercial'],['tax_id','NIF'],['status','Estado'],['address','Dirección'],['city','Localidad'],['province','Provincia'],['postal_code','Código postal'],['country','País'],['phone','Teléfono'],['email','Correo'],['notes','Observaciones']]; return <EntityForm title={title} fields={fields} initial={{ status: 'Activo', country: 'Espana', ...initial }} help={!initial?.id ? 'El código de cliente se generará automáticamente al guardar.' : undefined} errorMessage={initial?.id ? 'No se ha podido modificar el cliente.' : 'No se ha podido crear el cliente.'} onClose={onClose} onSubmit={(values: any) => initial?.id ? clientsService.update(initial.id, values) : clientsService.create(values)} onSaved={onSaved} />; }
